  description: 'Sovereign Awareness System transforming ecological data into human action.',
};

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <body className="bg-[#0b0f14] text-[#e5e7eb] min-h-screen font-sans selection:bg-[#3b82f6] selection:text-[#0b0f14]">
        <div className="flex flex-col min-h-screen">
          <header className="fixed top-0 w-full bg-[#111827]/80 backdrop-blur-md border-b border-[#1f2937] z-50 px-6 py-4 flex justify-between items-center">
            <div className="text-[#3b82f6] font-bold tracking-widest text-sm uppercase flex items-center gap-3">
              <span className="w-2 h-2 rounded-full bg-[#10b981] animate-pulse"></span>
              Forest Signal
            </div>
            <nav className="flex gap-8">
              <SovereignLink href="/region/kitanglad" lockId="sys_kitanglad">Mt. Kitanglad</SovereignLink>
