}

import { create } from 'zustand';

interface VibeState {
  drift_lock: string;
  activeLayer: 'satellite' | 'forest_loss' | 'regeneration';
  intensity: number;
  setDriftLock: (lock: string) => void;
  setActiveLayer: (layer: 'satellite' | 'forest_loss' | 'regeneration') => void;
  setIntensity: (intensity: number) => void;
}

export const useVibeStore = create<VibeState>((set) => ({
  drift_lock: 'init',
  activeLayer: 'satellite',
  intensity: 0,
  setDriftLock: (lock) => set({ drift_lock: lock }),
  setActiveLayer: (layer) => set({ activeLayer: layer }),
  setIntensity: (intensity) => set({ intensity }),
}));

import { useAnimation } from 'framer-motion';
import { useEffect } from 'react';
import { useVibeStore } from '@/store/useVibeStore';

export function useVolatilityMotion(baseScale: number = 1) {
  const controls = useAnimation();
  const intensity = useVibeStore((state) => state.intensity);

  useEffect(() => {
    // Motion language tied to TETRAFLUX: 
    // Higher intensity tightens constraints and accelerates transitions
    const dynamicScale = baseScale + (intensity * 0.02);
    const transitionDuration = 0.6 - (intensity * 0.05);

    controls.start({
      scale: dynamicScale,
      transition: { duration: Math.max(0.2, transitionDuration), ease: [0.16, 1, 0.3, 1] }
    });
  }, [intensity, baseScale, controls]);

  return controls;
}

'use client';

import Link from 'next/link';
import { motion } from 'framer-motion';
import { useVolatilityMotion } from '@/hooks/useVolatilityMotion';
import { useVibeStore } from '@/store/useVibeStore';
import { ReactNode } from 'react';

interface SovereignLinkProps {
  href: string;
  children: ReactNode;
  lockId: string;
}

export function SovereignLink({ href, children, lockId }: SovereignLinkProps) {
  const controls = useVolatilityMotion(1);
  const setDriftLock = useVibeStore((state) => state.setDriftLock);

  const handleClick = () => {
    setDriftLock(lockId);
  };

  return (
    <Link href={href} passHref legacyBehavior>
      <motion.a
        onClick={handleClick}
        animate={controls}
        whileHover={{ scale: 1.02, color: '#e5e7eb' }}
        whileTap={{ scale: 0.98 }}
        className="text-[#9ca3af] transition-colors duration-300 font-mono tracking-widest uppercase text-xs border-b border-transparent hover:border-[#3b82f6] pb-1 cursor-pointer"
      >
        {children}
      </motion.a>
    </Link>
  );
}

import { notFound } from 'next/navigation';
import { fetchRegionData } from '@/lib/actions';

interface RegionPageProps {
  params: { slug: string };
}

export default async function RegionPage({ params }: RegionPageProps) {
  const regionData = await fetchRegionData(params.slug);

  if (!regionData) {
    notFound();
  }

  return (
    <div className="max-w-7xl mx-auto px-6 w-full grid grid-cols-1 lg:grid-cols-12 gap-6">
      <div className="lg:col-span-4 flex flex-col gap-6">
        <div className="bg-[#111827] border border-[#1f2937] p-8 rounded-md shadow-2xl backdrop-blur-sm">
          <h1 className="text-2xl font-semibold text-[#e5e7eb] uppercase tracking-wider mb-3">
            {regionData.name}
          </h1>
          <p className="text-[#9ca3af] text-sm leading-relaxed mb-8">
            {regionData.description}
          </p>

          <div className="space-y-5">
            <div className="flex justify-between items-end border-b border-[#1f2937] pb-2">
              <span className="text-[#9ca3af] text-xs uppercase tracking-widest font-mono">Forest Cover</span>
              <span className="text-[#3b82f6] font-mono text-xl tracking-tight">{regionData.forestCover}%</span>
            </div>
            <div className="flex justify-between items-end border-b border-[#1f2937] pb-2">
              <span className="text-[#9ca3af] text-xs uppercase tracking-widest font-mono">Recovery</span>
              <span className="text-[#10b981] font-mono text-xl tracking-tight">+{regionData.regenerationRate}%</span>
            </div>
          </div>
        </div>

        <div className="bg-[#111827] border border-[#1f2937] p-8 rounded-md shadow-2xl">
          <h3 className="text-[#e5e7eb] font-medium mb-5 uppercase text-xs tracking-widest">Targeted Action</h3>
          <button className="w-full bg-transparent border border-[#10b981] text-[#10b981] hover:bg-[#10b981] hover:text-[#0b0f14] transition-all duration-300 py-3 rounded text-xs font-bold uppercase tracking-widest">
            Engage Restoration
          </button>
        </div>
      </div>

      <div className="lg:col-span-8 bg-[#111827] border border-[#1f2937] rounded-md shadow-2xl overflow-hidden relative min-h-[600px] flex items-center justify-center">
        {/* Map Visualization Placeholder */}
        <div className="absolute inset-0 bg-[#0b0f14] opacity-50"></div>
        <div className="z-10 text-center">
          <p className="text-[#3b82f6] font-mono text-xs uppercase tracking-widest mb-2">
            [ Sensory Subsystem Active ]
          </p>
          <p className="text-[#9ca3af] font-mono text-xs">
            Location: {regionData.coordinates}
          </p>
        </div>
        {/* UI Overlay layer simulating TETRAFLUX integration */}
        <div className="absolute bottom-6 right-6 flex gap-2">
          <div className="h-1 w-8 bg-[#3b82f6] opacity-80 rounded-full"></div>
          <div className="h-1 w-8 bg-[#10b981] opacity-40 rounded-full"></div>
          <div className="h-1 w-8 bg-[#1f2937] opacity-40 rounded-full"></div>
        </div>
      </div>
    </div>
  );
}

'use server';

import { revalidatePath } from 'next/cache';

// Deterministic mocked database interaction for the scaffold
export async function fetchRegionData(slug: string) {
  const regions: Record<string, any> = {
    'kitanglad': {
      name: 'Mt. Kitanglad Range',
      description: 'Ancestral domain of the Talaandig, Higaonon, and Bukidnon tribes. A critical watershed requiring vigilant observation and memory preservation.',
      forestCover: 68.4,
      regenerationRate: 2.1,
      coordinates: '8.1333° N, 124.9167° E'
    },
    'kalatungan': {
      name: 'Mt. Kalatungan Range',
      description: 'High altitude volcanic mountain range. Ecological pressure points visualized through satellite degradation telemetry.',
      forestCover: 52.8,
      regenerationRate: 1.4,
      coordinates: '7.9500° N, 124.8000° E'
    }
  };

  return regions[slug] || null;
}

export async function logRestorationActivity(formData: FormData) {
  const location = formData.get('location');
  const type = formData.get('type'); // 'planting' | 'monitoring'

  // Simulated systemic persistence latency
  await new Promise(resolve => setTimeout(resolve, 600));

  console.log(`[FOREST SIGNAL] Action logged: ${type} at ${location}`);

  revalidatePath(`/region/${location}`);
  return { success: true, message: 'Ecological awareness recorded and synchronized.' };
}
